"""Profile page e2e: stats, editing through BetterAuth, JWT carries the new name, route guard."""
import re, time, json, base64
exec(open("scripts/e2e/booknook_phase6_e2e.py").read().split("stamp=str")[0])
stamp=str(int(time.time()))
with sync_playwright() as p:
    br=p.chromium.launch()
    anon=br.new_context().new_page(); anon.goto(BASE+"/profile"); anon.wait_for_url(re.compile(r"/login\?callbackUrl="))
    check("logged-out /profile -> login with callback", "profile" in anon.url)
    al=user_page(br,"Pat Owner",f"palice{stamp}@t.dev"); bo=user_page(br,"Pat Reader",f"pbob{stamp}@t.dev")
    ids=[call(al,"POST","/books",{"title":f"Profile Book {i} {stamp}","author":"A B","category":"Others","image":"https://i.ibb.co/x.png","description":"twenty plus characters of description here","totalCopies":2})["json"]["data"]["_id"] for i in range(2)]
    for i in ids: call(bo,"POST","/borrows",{"bookId":i,"returnDate":due()})
    rid=call(bo,"GET","/borrows")["json"]["data"][0]["_id"]; call(bo,"DELETE",f"/borrows/{rid}")
    bo.goto(BASE+"/profile"); bo.wait_for_selector("dt:has-text('Returned')")
    check("title is 'BookNook | My Profile'", bo.title()=="BookNook | My Profile", bo.title())
    check("shows name, email and member-since", bo.locator("h2:has-text('Pat Reader')").count()==1 and bo.locator(f"text=pbob{stamp}@t.dev").count()>=1 and bo.locator("text=Member since").count()==1)
    vals=[bo.locator(f"dl div:has(dt:text-is('{l}')) dd").inner_text() for l in ("Borrowed now","Returned","Books added")]
    check("stats from the real API: borrowed 1, returned 1, added 0", vals==["1","1","0"], str(vals))
    al.goto(BASE+"/profile"); al.wait_for_selector("dt:has-text('Books added')")
    check("owner stats: added 2, borrowed 0", al.locator("dl div:has(dt:text-is('Books added')) dd").inner_text()=="2" and al.locator("dl div:has(dt:text-is('Borrowed now')) dd").inner_text()=="0")
    check("email field is read-only", bo.get_attribute("#email","readonly") is not None)
    check("no manual photo-URL field on the profile page", bo.locator("#photoUrl").count()==0)
    bo.fill("#name","P"); bo.click("button:has-text('Save changes')")
    check("profile validation error shown", bo.locator("[role=alert]").count()>=1)
    bo.fill("#name","Pat Renamed"); bo.click("button:has-text('Save changes')")
    bo.wait_for_selector("h2:has-text('Pat Renamed')",timeout=10000)
    check("name updated on the page", True)
    bo.reload(); check("update persisted after reload", bo.locator("h2:has-text('Pat Renamed')").count()==1)
    tok=token(bo); payload=json.loads(__import__("base64").urlsafe_b64decode(tok.split(".")[1]+"=="))
    check("new JWT carries the updated name", payload["name"]=="Pat Renamed", payload["name"])
    nm=call(bo,"GET","/borrows")["json"]["data"]; check("API still authenticates after rename", len(nm)==2)

    # ---- profile picture upload (real session, real /api/upload proxy, stub host)
    PNG=base64.b64decode("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==")
    def me(pg): return pg.evaluate("fetch('/api/auth/get-session').then(r=>r.json()).then(j=>j.user)")
    bo.goto(BASE+"/profile"); bo.wait_for_selector("button:has-text('Change photo')")
    check("existing (unreachable) photo falls back to initials avatar; Change photo offered", bo.locator("main >> text=PR").count()>=1 and bo.locator("button:has-text('Change photo')").count()==1)
    bo.set_input_files("#avatar-file",{"name":"x.txt","mimeType":"text/plain","buffer":b"nope"}); bo.wait_for_selector("text=Use a JPG, PNG, WebP or GIF image")
    check("non-image rejected before upload", bo.locator("button:has-text('Save photo')").count()==0)
    bo.set_input_files("#avatar-file",{"name":"fake.png","mimeType":"image/png","buffer":b"not really a png"}); bo.click("button:has-text('Save photo')"); bo.wait_for_selector("text=does not look like a valid image",timeout=10000)
    check("fake image rejected by the server proxy (error message shown)", True)
    bo.reload(); bo.wait_for_selector("dt:has-text('Returned')")
    before=me(bo).get("image")
    bo.set_input_files("#avatar-file",{"name":"me.png","mimeType":"image/png","buffer":PNG}); bo.wait_for_selector("text=Preview. Save to use this photo.")
    check("preview shown before saving, profile not yet changed", me(bo).get("image")==before and bo.locator("button:has-text('Save photo')").count()==1)
    bo.click("button:has-text('Save photo')"); bo.wait_for_selector("button:has-text('Change photo')",timeout=20000)
    img1=me(bo).get("image"); check("photo saved to the real profile (stub host URL)", bool(img1) and img1.startswith("https://i.ibb.co/stub/"), str(img1))
    bo.reload(); bo.wait_for_selector("button:has-text('Change photo')")
    check("photo persists after reload; initials replaced by image", me(bo).get("image")==img1)
    bo.set_input_files("#avatar-file",{"name":"me2.png","mimeType":"image/png","buffer":PNG}); bo.click("button:has-text('Save photo')"); bo.wait_for_function("true"); bo.wait_for_timeout(2500)
    img2=me(bo).get("image"); check("photo can be replaced with a new upload", bool(img2) and img2!=img1, str(img2))
    check("JWT/API still work after photo change", len(call(bo,"GET","/borrows")["json"]["data"])==2)
    bo.set_viewport_size({"width":390,"height":844}); bo.goto(BASE+"/profile"); bo.wait_for_selector("dt:has-text('Returned')")
    check("no horizontal overflow at 390px", bo.evaluate("document.documentElement.scrollWidth<=document.documentElement.clientWidth"))
    bo.screenshot(path="/tmp/profile-mobile.png",full_page=True)
    bo.set_viewport_size({"width":1440,"height":900}); bo.goto(BASE+"/profile"); bo.wait_for_selector("dt:has-text('Returned')"); bo.screenshot(path="/tmp/profile-desktop.png")
    br.close()
bad=[r for r in results if not r[1]]; print(f"\n{len(results)-len(bad)}/{len(results)} passed")
